// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.nio.ByteBuffer;
import java.util.List;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class TermIndexBuildTest {
	@ParameterizedTest
	@ValueSource(strings = { "posc,spoc,cspo", "spoc,posc,cspo", "cspo,posc,spoc" })
	void descriptorPreservesThePrimaryIndexAcrossConstructionAndRoundTrip(String sourceSpecs) {
		var source = TripleIndex.parseIndexSpecList(sourceSpecs);
		var target = TripleIndex.parseIndexSpecList("opsc,spoc,cspo");
		TermIndexBuild build = new TermIndexBuild(source, target, TermIndexBuild.COPY, null, 9L, new byte[16]);
		assertEquals(source.iterator().next(), build.source().iterator().next());
		assertEquals("opsc", build.target().iterator().next());
		TermIndexBuild decoded = TermIndexBuild.decode(ByteBuffer.wrap(build.encode(10L)));
		assertNotNull(decoded);
		assertEquals(source.iterator().next(), decoded.source().iterator().next());
		assertEquals("opsc", decoded.target().iterator().next());
		assertEquals(List.copyOf(TripleIndex.orderIndexSpecs(source)), List.copyOf(decoded.source()));
	}
}
